#!/usr/bin/env bash
# Replace alembic/versions/* with ONE initial revision autogenerated against an empty scratch database.
# Pre-release only: once a deployment exists, use scripts/new-migration.sh instead.
set -euo pipefail
cd "$(dirname "$0")/../backend"
rm -f alembic/versions/*.py
SCRATCH="$(uv run python -m app.modules.ops.dbtools create-scratch)"
trap 'uv run python -m app.modules.ops.dbtools drop "$SCRATCH" >/dev/null 2>&1 || true' EXIT
VOLTORA_DATABASE_URL="$SCRATCH" uv run alembic revision --autogenerate --rev-id 0001 -m "initial schema"
echo "Regenerated backend/alembic/versions/0001_initial_schema.py. Review it, then: cd backend && uv run pytest -q tests/test_migrations.py"
